<?php
/** Plugin Name: TEMP PS S1724e deploy: petshop-dropship-sargas v1.1 (2 darbo d.) + 3 zymiu nuemimas + rytas tekstas. Fazes: 1 lint+dry terminai, 2 plugin, 3 nuimti zymes 36288/36296/36298, 4 rytas tekstas, 5 patikra, 9 atstatyti */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1724e'])) return; $f=(string)$_GET['ps_s1724e']; $r=['v'=>'S1724e','faze'=>$f]; global $wpdb; $P=$wpdb->prefix; @set_time_limit(170); $tz=wp_timezone();
  $B1='';
  $mu=WPMU_PLUGIN_DIR; $plug=$mu.'/petshop-dropship-sargas.php'; $rytas=$mu.'/petshop-rytas.php';
  $arch=dirname(untrailingslashit(ABSPATH)).'/ps-archyvas'; $r['arch']=is_dir($arch)?'ok':'NERA '.$arch;
  $tok=function($code){ try{ token_get_all($code,TOKEN_PARSE); return 'ok'; }catch(Throwable $e){ return 'KLAIDA '.$e->getMessage(); } };
  $hb=function() use(&$r){ for($i=0;$i<2;$i++){ $x=wp_remote_get(home_url('/?ps_hb='.time()),['timeout'=>25,'sslverify'=>false]); $c=is_wp_error($x)?'ERR '.$x->get_error_message():wp_remote_retrieve_response_code($x); if($c===200) return 200; sleep(2);} return $c; };
  $rytas_patch=function($s){ $s=str_replace("'Dropship tiekėjas vėluoja > 24 val.: '","'Dropship tiekėjas vėluoja > 2 darbo d.: '",$s,$c1); $s=str_replace(" * Version: 1.6\n"," * Version: 1.6.1\n",$s,$c2); return [$s,[$c1,$c2]]; };
  $ids=[36288,36296,36298];
  try{
    if($f==='1'){
      $code=base64_decode($B1); $r['lint']=$tok($code); $r['plugin_md5_dabar']=md5_file($plug); $r['plugin_ver_dabar']=preg_match('#Version:\s*([\d.]+)#',file_get_contents($plug),$m)?$m[1]:'1.0 (be Version)';
      list($rs,$rc)=$rytas_patch(file_get_contents($rytas)); $r['rytas_counts']=$rc; $r['lint_rytas']=$tok($rs); $r['rytas_md5_dabar']=md5_file($rytas);
      // dry: nauja klase po kitu vardu – ivertinti terminus
      $dry=str_replace('Petshop_Dropship_Sargas','PS_DS_Dry_S1724',$code); $dry=preg_replace('#PS_DS_Dry_S1724::init\(\);\s*$#','',$dry); eval('?>'.$dry);
      foreach(['2026-09-25 11:13:31','2026-09-24 14:22:00','2026-09-26 12:00:00','2026-09-27 10:00:00','2026-11-01 10:00:00','2026-09-21 09:00:00'] as $s){ $t=PS_DS_Dry_S1724::terminas($s); $r['pvz'][$s]=$t?$t->format('Y-m-d H:i D').($t->getTimestamp()<time()?' VELUOJA':' laukiam'):null; }
      $r['dry_kandidatai']=PS_DS_Dry_S1724::tikrinti(true);
      // visi processing su _ps_dropship_sent (ir su zyme) – kaip butu vertinami
      $rows=$wpdb->get_results("SELECT o.id, m.meta_value sent, (SELECT meta_value FROM {$P}wc_orders_meta z WHERE z.order_id=o.id AND z.meta_key='_ps_sla_velavimas' LIMIT 1) zyme FROM {$P}wc_orders o JOIN {$P}wc_orders_meta m ON m.order_id=o.id AND m.meta_key='_ps_dropship_sent' WHERE o.status IN ('wc-processing','wc-on-hold') AND m.meta_value<>''",ARRAY_A);
      foreach($rows as $x){ $t=PS_DS_Dry_S1724::terminas($x['sent']); $r['atviri_su_sent'][]=[$x['id'],$x['sent'],$t?$t->format('m-d H:i D'):null,$t&&$t->getTimestamp()<time()?'VELUOJA':'ok',$x['zyme']]; }
      $r['darbalaukis_helper']=class_exists('Petshop_Darbalaukis')&&method_exists('Petshop_Darbalaukis','darbo_diena');
    }
    if($f==='2'){
      $code=base64_decode($B1); if($tok($code)!=='ok') throw new Exception('lint'); if(!file_exists($arch.'/petshop-dropship-sargas.php.bak_s1724')) copy($plug,$arch.'/petshop-dropship-sargas.php.bak_s1724');
      file_put_contents($plug,$code); $r['md5']=md5_file($plug); $r['heartbeat']=$hb(); if($r['heartbeat']!==200){ copy($arch.'/petshop-dropship-sargas.php.bak_s1724',$plug); $r['ROLLBACK']='v1.0 atstatytas'; }
    }
    if($f==='3'){
      $bak=get_option('ps_s1724_sla_bak',[]);
      foreach($ids as $id){ $o=wc_get_order($id); if(!$o) continue; $z=$o->get_meta('_ps_sla_velavimas'); if($z===''){ $r['nuimta'][]=$id.' (zymes nebuvo)'; continue; } if(!isset($bak[$id])) $bak[$id]=$z;
        $o->delete_meta_data('_ps_sla_velavimas'); $o->add_order_note('S1724 (Raimis, 09-27): SLA žymė nuimta — 24 val. skaičiuotos per savaitgalį. Nuo v1.1 sargas skaičiuoja 2 darbo dienas; jei tiekėjas neišsiųs iki termino, pažymės iš naujo.',false,true); $o->save(); $r['nuimta'][]=$id.' ('.$z.')'; }
      update_option('ps_s1724_sla_bak',$bak,false);
      $r['liko_zymiu']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$P}wc_orders_meta m JOIN {$P}wc_orders o ON o.id=m.order_id WHERE m.meta_key='_ps_sla_velavimas' AND o.status IN ('wc-processing','wc-on-hold')");
    }
    if($f==='4'){
      $s1=file_get_contents($rytas); list($rs,$rc)=$rytas_patch($s1); if($rc[0]!==1||$tok($rs)!=='ok') throw new Exception('rytas patch '.json_encode($rc).' '.$tok($rs));
      if(!file_exists($arch.'/petshop-rytas.php.bak_s1724')) copy($rytas,$arch.'/petshop-rytas.php.bak_s1724'); file_put_contents($rytas,$rs); $r['rytas_md5']=md5_file($rytas); $r['rytas_counts']=$rc;
      $r['heartbeat']=$hb(); if($r['heartbeat']!==200){ copy($arch.'/petshop-rytas.php.bak_s1724',$rytas); $r['ROLLBACK']='rytas atstatytas'; }
    }
    if($f==='5'){ // patikra atskira uzklausa
      $r['plugin_md5']=md5_file($plug); $r['plugin_ver']=preg_match('#Version:\s*([\d.]+)#',file_get_contents($plug),$m)?$m[1]:null; $r['rytas_md5']=md5_file($rytas);
      $r['klase']=class_exists('Petshop_Dropship_Sargas'); $r['valandu']=Petshop_Dropship_Sargas::valandu(); $r['cron_kitas']=($n=wp_next_scheduled('ps_dropship_sargas'))?(new DateTime('@'.$n))->setTimezone($tz)->format('m-d H:i'):null;
      $r['tikrinti_dry']=Petshop_Dropship_Sargas::tikrinti(true); $r['tikrinti_realus']=Petshop_Dropship_Sargas::tikrinti();
      $r['zymiu_atviru']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$P}wc_orders_meta m JOIN {$P}wc_orders o ON o.id=m.order_id WHERE m.meta_key='_ps_sla_velavimas' AND o.status IN ('wc-processing','wc-on-hold')");
      if(class_exists('Petshop_Rytas')){ $m=new ReflectionMethod('Petshop_Rytas','patikros'); $m->setAccessible(true); $pt=$m->invoke(null); foreach($pt as $x){ if($x['kodas']==='dropship_sla') $r['rytas_lempute']=$x; } $r['rytas_lempuciu']=count($pt); $r['rytas_raudonos']=array_values(array_filter(array_map(function($x){return $x['lygis']==='raudona'?$x['kodas']:null;},$pt))); }
      $r['heartbeat']=$hb();
    }
    if($f==='9'){
      if(file_exists($arch.'/petshop-dropship-sargas.php.bak_s1724')){ copy($arch.'/petshop-dropship-sargas.php.bak_s1724',$plug); $r['plugin']=md5_file($plug); }
      if(file_exists($arch.'/petshop-rytas.php.bak_s1724')){ copy($arch.'/petshop-rytas.php.bak_s1724',$rytas); $r['rytas']=md5_file($rytas); }
      foreach((array)get_option('ps_s1724_sla_bak',[]) as $id=>$z){ $o=wc_get_order($id); if($o){ $o->update_meta_data('_ps_sla_velavimas',$z); $o->save(); $r['zyme_grazinta'][]=$id; } }
      $r['heartbeat']=$hb();
    }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
}, 1);
